using System;
using System.Collections.Generic;

namespace DDDToolkit.Analyzers.Common;

/// <summary>Pieces of generated code shared by all emitters.</summary>
internal static class Emit
{
    /// <summary>Standard header: auto-generated marker, nullable context and the warnings generated code may trip.</summary>
    public static CodeWriter Header(this CodeWriter writer)
    {
        writer.Directive("// <auto-generated/>");
        writer.Directive("#nullable enable");
        writer.Directive("#pragma warning disable CS1591, CS8618, CS8669");
        writer.Line();
        return writer;
    }

    /// <summary>
    /// Enters the type's namespace and containing types. Dispose the result to close the containing
    /// types again. Nested types are re-opened as partial declarations.
    /// </summary>
    public static IDisposable TypeScope(this CodeWriter writer, TypeDeclarationInfo type)
    {
        if (type.Namespace.Length > 0)
        {
            writer.Line("namespace " + type.Namespace + ";");
            writer.Line();
        }

        var closers = new Stack<IDisposable>();
        foreach (var header in type.ContainingTypeHeaders)
        {
            closers.Push(writer.Block(header));
        }

        return new Scope(closers);
    }

    /// <summary>
    /// Equality for a type whose only equality component is <c>Value</c>: entity ids and single value
    /// objects. Compares the value directly instead of walking <c>GetEqualityComponents()</c>.
    /// <para>
    /// The result is identical, because both implementations yield exactly one component, but the walk
    /// is an <c>IEnumerable&lt;object&gt;</c> iterator plus LINQ, so every comparison allocated two
    /// iterators and boxed the value. Measured at 144 bytes and roughly 30ns a comparison, which made a
    /// dictionary keyed by a record id 17 times slower than one keyed by a struct id. See
    /// docs/performance.md.
    /// </para>
    /// </summary>
    /// <param name="valueIsValueType">
    /// Whether <c>Value</c> is a value type. A non-nullable value type cannot be tested against null
    /// (CS0037), and a reference-typed value can be null on a default instance, where the walk this
    /// replaces produced a hash of zero. The two cases therefore need different hash code bodies.
    /// </param>
    public static void SingleValueEqualityMembers(CodeWriter writer, string typeName, string valueType, bool valueIsValueType)
    {
        var comparer = "global::System.Collections.Generic.EqualityComparer<" + valueType + ">.Default";

        using (writer.Block("public virtual bool Equals(" + typeName + "? other)"))
        {
            writer.Line("if (other is null)");
            writer.Line("{");
            writer.Line("    return false;");
            writer.Line("}");
            writer.Line();
            EqualityContractCheck(writer);
            writer.Line("if (ReferenceEquals(this, other))");
            writer.Line("{");
            writer.Line("    return true;");
            writer.Line("}");
            writer.Line();
            writer.Line("return " + comparer + ".Equals(Value, other.Value);");
        }

        writer.Line();

        if (valueIsValueType)
        {
            writer.Line("public override int GetHashCode() => " + comparer + ".GetHashCode(Value);");
        }
        else
        {
            // The walk this replaces mapped a null component to zero; keep that rather than throwing.
            writer.Line("public override int GetHashCode() => Value is null ? 0 : " + comparer + ".GetHashCode(Value);");
        }
    }

    /// <summary>
    /// <c>ISingleValue&lt;TSelf, TValue&gt;</c> closed over a type and its value, for the type's base list: what lets a
    /// project that does not declare the type store it as its value, through one generic converter.
    /// </summary>
    public static string SingleValueInterface(string typeName, string valueType)
        => KnownTypes.SingleValueInterfaceUsage + "<" + typeName + ", " + valueType + ">";

    /// <summary>
    /// The explicit <c>FromValue</c> of <see cref="SingleValueInterface"/>. It does exactly what the converter the
    /// Entity Framework generator nests in the type does, <c>new(value)</c>: for the plain type the constructor
    /// that does not check, for the always-valid twin its public constructor that validates. Explicit, so it adds
    /// nothing to the members a caller sees on the type.
    /// </summary>
    public static void SingleValueFromValue(CodeWriter writer, string typeName, string valueType)
    {
        writer.Line("/// <summary>The value read back from storage by code that does not know this type. Not a factory: see ISingleValue.</summary>");
        writer.Line("static " + typeName + " " + SingleValueInterface(typeName, valueType) + ".FromValue(" + valueType + " value) => new(value);");
    }

    /// <summary>
    /// Equality for a <c>[ValueObject]</c> and its twin: each compared property directly, in declaration order,
    /// with <c>EqualityComparer&lt;T&gt;.Default</c> of its own type.
    /// <para>
    /// It used to walk <c>GetEqualityComponents()</c> with <c>SequenceEqual</c>, and hash it with
    /// <c>Aggregate</c>. Every comparison then allocated two iterators and boxed each value-type property
    /// twice. The hash had no seed, so a value object without compared properties threw on
    /// <c>GetHashCode()</c>. It combined with XOR, so (a, b) and (b, a) had the same hash. The answer of
    /// <c>Equals</c> is the same: the components are the same properties, compared by the same equality.
    /// </para>
    /// </summary>
    /// <param name="components">The compared properties, by name and type.</param>
    /// <param name="hashCodeFromComponents">
    /// Whether to write the hash. The twin takes the hash of the value object it derives from, which compares
    /// the same properties.
    /// </param>
    public static void RecordEqualityMembers(
        CodeWriter writer,
        string typeName,
        IReadOnlyList<(string Name, string TypeName)> components,
        bool hashCodeFromComponents)
    {
        using (writer.Block("public virtual bool Equals(" + typeName + "? other)"))
        {
            writer.Line("if (other is null)");
            writer.Line("{");
            writer.Line("    return false;");
            writer.Line("}");
            writer.Line();
            EqualityContractCheck(writer);
            writer.Line("if (ReferenceEquals(this, other))");
            writer.Line("{");
            writer.Line("    return true;");
            writer.Line("}");
            writer.Line();

            if (components.Count == 0)
            {
                writer.Line("return true;");
            }
            else
            {
                for (var index = 0; index < components.Count; index++)
                {
                    var (name, type) = components[index];
                    var compare = "global::System.Collections.Generic.EqualityComparer<" + type + ">.Default.Equals(" + name + ", other." + name + ")";
                    var start = index == 0 ? "return " : "    && ";
                    var end = index == components.Count - 1 ? ";" : string.Empty;
                    writer.Line(start + compare + end);
                }
            }
        }

        writer.Line();

        if (!hashCodeFromComponents)
        {
            writer.Line("public override int GetHashCode() => base.GetHashCode();");
            return;
        }

        using (writer.Block("public override int GetHashCode()"))
        {
            writer.Line("var hash = new global::System.HashCode();");
            foreach (var (name, type) in components)
            {
                writer.Line("hash.Add(" + name + ", global::System.Collections.Generic.EqualityComparer<" + type + ">.Default);");
            }

            writer.Line("return hash.ToHashCode();");
        }
    }

    /// <summary>
    /// Refuses an <c>other</c> of a different runtime type, as the compiler's own record equality does.
    /// <para>
    /// Without it a value and its always-valid twin were equal one way only: <c>plain.Equals(twin)</c>
    /// compared components and said yes, while <c>twin.Equals(plain)</c> went through the
    /// <c>Equals(Base?)</c> the compiler synthesizes in a derived record, which casts to the twin type
    /// and said no. The compiler does not allow that override to be declared, so "equal both ways"
    /// cannot be built; "unequal both ways" is the symmetric choice left.
    /// </para>
    /// </summary>
    private static void EqualityContractCheck(CodeWriter writer)
    {
        writer.Line("if (EqualityContract != other.EqualityContract)");
        writer.Line("{");
        writer.Line("    return false;");
        writer.Line("}");
        writer.Line();
    }

    private sealed class Scope(Stack<IDisposable> closers) : IDisposable
    {
        public void Dispose()
        {
            while (closers.Count > 0)
            {
                closers.Pop().Dispose();
            }
        }
    }
}
